import {localDay} from './schedule.js';
export function validateSlots(slots){if(!Array.isArray(slots)||slots.length>8)throw Error('Use up to eight time slots.');let previous=-1;for(const slot of [...slots].sort((a,b)=>String(a.start).localeCompare(String(b.start)))){if(!slot||!/^([01]\d|2[0-3]):[0-5]\d$/.test(slot.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(slot.end))throw Error('Enter a start and end time for every slot.');const minute=t=>+t.slice(0,2)*60+ +t.slice(3),start=minute(slot.start),end=minute(slot.end);if(end<=start)throw Error('Each slot must end after it starts on the same day.');if(start<previous)throw Error('Time slots cannot overlap.');previous=end;}}
export function occurrenceTiming(s,m,originalAt=m.dueAt){const originalDay=originalAt?localDay(originalAt):'',records=s.calendarOverrides?.[m.seriesId]||{},entry=records[originalDay]&&localDay(records[originalDay].originalAt)===originalDay?[originalDay,records[originalDay]]:Object.entries(records).find(([,o])=>localDay(o.originalAt)===originalDay),override=entry?.[1],deadline=override?.deadline||originalAt;return {originalAt,originalDay,overrideKey:entry?.[0]||originalDay,deadline,day:deadline?localDay(deadline):'',slots:override?.slots??m.calendar.slots??[],allDay:override?.allDay??m.calendar.allDay,adjusted:!!override};}
export const effectiveDeadline=(s,m)=>occurrenceTiming(s,m).deadline;
export function slotDates(timing,slot){return {start:new Date(`${timing.day}T${slot.start}:00`),end:new Date(`${timing.day}T${slot.end}:00`)};}
export function validateTiming(s){if(!s.calendarOverrides||typeof s.calendarOverrides!=='object'||Array.isArray(s.calendarOverrides))throw Error('Invalid date overrides.');for(const m of s.missions){validateSlots(m.calendar.slots);if(m.calendar.allDay&&m.calendar.slots.length)throw Error('All-day events cannot also have time slots.');}for(const [series,dates] of Object.entries(s.calendarOverrides)){if(typeof series!=='string'||['__proto__','constructor','prototype'].includes(series)||!dates||typeof dates!=='object'||Array.isArray(dates)||Object.keys(dates).length>1000)throw Error('Invalid date-specific schedule.');for(const [day,o] of Object.entries(dates)){if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!o||!Number.isFinite(Date.parse(o.originalAt))||!Number.isFinite(Date.parse(o.deadline))||typeof o.allDay!=='boolean')throw Error('Invalid date override.');validateSlots(o.slots);if(o.allDay&&o.slots.length)throw Error('All-day overrides cannot also have time slots.');}}}
